#include "local_candidate_background.hpp"
#include <QCoreApplication>
#include <QFile>
#include <QJsonDocument>
#include <QTextStream>
#include <stdexcept>
static void check(bool b,const char*m){if(!b)throw std::runtime_error(m);}
static QJsonObject read(QString p){QFile f(p);check(f.open(QIODevice::ReadOnly),"read fixture");return QJsonDocument::fromJson(f.readAll()).object();}
int main(int argc,char**argv){QCoreApplication app(argc,argv);try{check(argc==4,"paths required");auto fixture=read(argv[1]);QJsonArray output;for(QString group:{"cases","negatives"})for(auto v:fixture[group].toArray()){auto c=v.toObject();auto r=localCandidateBackground::evaluate(c["background"].toObject(),c["id"].toString(),c["strategy"].toString(),QDateTime::fromString(c["capturedAt"].toString(),Qt::ISODate));if(group=="cases"){check(r["completeDelta"]==c["expectedDelta"],"actual old delta mismatch");check(r["status"]=="complete","known input complete");}else{check(r["completeDelta"].isNull(),"unknown is not zero");for(auto rule:c["expectedUnknown"].toArray()){bool found=false;for(auto f:r["factors"].toArray())if(f.toObject()["rule"]==rule)found=f.toObject()["points"].isNull();check(found,"unknown rule incorrectly scored");}}output.append(QJsonObject{{"name",c["name"]},{"evaluation",r}});}
 auto old=read(argv[2]);QJsonObject selectedCase;for(auto v:old["cases"].toArray()){auto c=v.toObject();if(c.contains("error"))continue;auto rows=c["result"].toObject()["rows"].toArray();if(!rows.isEmpty()&&rows[0].toObject()["rawScore"].isDouble()){selectedCase=c;break;}}check(!selectedCase.isEmpty(),"eligible v1 fixture");auto selected=selectedCase["selected"].toArray();auto at=QDateTime::fromString(selectedCase["capturedAt"].toString(),Qt::ISODate);auto baseline=localCandidate::evaluate(localCandidate::snapshot(selected,selectedCase["strategy"].toString(),at));localCandidate::verify(baseline);check(baseline["model"]==localCandidate::version,"v1 preserved");
 auto s=selected[0].toObject();auto bg=fixture["cases"].toArray().last().toObject()["background"].toObject();QString serialized=QString::fromUtf8(QJsonDocument(bg).toJson(QJsonDocument::Compact));serialized.replace("SH:stock:600001",s["id"].toString()).replace("2026-10-13T08:00:00Z",selectedCase["capturedAt"].toString()).replace("2026-10-13T07:00:00Z",selectedCase["capturedAt"].toString());s["backgroundInput"]=QJsonDocument::fromJson(serialized.toUtf8()).object();selected[0]=s;auto frozen=localCandidate::snapshot(selected,selectedCase["strategy"].toString(),at);auto result=localCandidate::evaluate(frozen);localCandidate::verify(result);QJsonObject baseRow,newRow;for(auto v:baseline["rows"].toArray())if(v.toObject()["id"]==s["id"])baseRow=v.toObject();for(auto v:result["rows"].toArray())if(v.toObject()["id"]==s["id"])newRow=v.toObject();check(newRow["factors"]==baseRow["factors"],"technical factors unchanged");check(newRow["rawScore"].toInt()==baseRow["rawScore"].toInt()+newRow["backgroundEvaluation"].toObject()["knownDelta"].toInt(),"apply delta once before clamp");int sum=0;for(auto v:newRow["contributions"].toArray())sum+=v.toObject()["points"].toInt();check(sum==newRow["rawScore"].toInt(),"contributions conserve raw score");check(result["model"]==localCandidateBackground::candidateVersion,"v2 model");check(result["inputHash"]!=baseline["inputHash"],"input digest binds background");check(localCandidate::csv(result).contains("native-local-candidates/v2-background"),"CSV actual model");auto bad=result;auto rows=bad["rows"].toArray();auto row=rows[0].toObject();row["rawScore"]=999;rows[0]=row;bad["rows"]=rows;bool rejected=false;try{localCandidate::verify(bad);}catch(...){rejected=true;}check(rejected,"tamper rejected");rejected=false;try{localCandidate::evaluate(frozen,[]{return true;});}catch(...){rejected=true;}check(rejected,"cancelled");
 auto excluded=QJsonObject{{"id",s["id"]},{"score",QJsonValue::Null},{"rawScore",QJsonValue::Null},{"status","excluded"},{"contributions",QJsonArray{}},{"missing",QJsonArray{}}};auto applied=localCandidateBackground::apply(excluded,s["backgroundInput"].toObject(),selectedCase["strategy"].toString(),at);check(applied["score"].isNull()&&applied["status"]=="excluded","background cannot rescue excluded technical input");
 QFile f(argv[3]);check(f.open(QIODevice::WriteOnly),"write own parity output");f.write(QJsonDocument(output).toJson(QJsonDocument::Compact));QTextStream(stdout)<<"PASS Qt: 128 actual-old deltas, 20 adversarial inputs, v1/v2 replay, digest/tamper/CSV/cancel/exclusion\n";return 0;}catch(const std::exception&e){QTextStream(stderr)<<e.what()<<'\n';return 1;}}


